def score(program: str) -> float:
    n = len(program)
    if n == 0:
        return 0.0
    ws = sum(c.isspace() for c in program) / n
    div = len(set(program)) / 64
    return min(1.0, max(0.0, 0.5 * ws * 2 + 0.5 * min(div, 1.0)))

